/**
 * Central image library. Every image on the public site is referenced by key,
 * so swapping in commissioned photography only means replacing the file (same
 * name, similar aspect ratio) or editing the entry here.
 *
 * The current files are procedurally rendered material studies generated by
 * scripts/generate-images.py. They depict fabrics and textile objects only —
 * never a facility, person or product attributed to Sourcing Eleven.
 */
export type ImageEntry = { src: string; alt: string; width: number; height: number };

const img = (file: string, alt: string, width = 1600, height = 1200): ImageEntry => ({
  src: `/images/${file}`,
  alt,
  width,
  height,
});

export const images = {
  heroSilk: img("hero-navy-silk.jpg", "Deep navy satin fabric falling in soft folds, lit with a warm champagne highlight", 2400, 1350),
  linenIvory: img("linen-ivory-folds.jpg", "Ivory slub linen gathered in loose vertical folds", 1600, 2000),
  champagneSilk: img("champagne-silk.jpg", "Champagne-gold satin with gentle drape and soft sheen"),
  denimTwill: img("denim-twill.jpg", "Indigo denim twill fabric in rolling folds"),
  waffleCotton: img("waffle-cotton.jpg", "White waffle-weave cotton with a raised grid texture"),
  jerseyKnit: img("jersey-knit.jpg", "Slate-grey single jersey knit fabric in close-up"),
  undyedCotton: img("undyed-cotton.jpg", "Undyed natural ecru cotton showing its slub texture"),
  terry: img("terry-towelling.jpg", "Sand-coloured terry towelling with dense looped pile"),
  swatchFan: img("swatch-fan.jpg", "A fan of fabric swatches in navy, ecru, gold, indigo and slate"),
  labDips: img("lab-dips.jpg", "A grid of pinked-edge colour swatches laid out for shade approval"),
  bolts: img("fabric-bolts.jpg", "Rolled fabric bolts stacked end-on in navy, ivory and gold tones"),
  stacks: img("folded-stacks.jpg", "Two neat stacks of folded textiles in alternating navy and neutral shades"),
  warp: img("warp-threads.jpg", "Parallel warp threads in navy with occasional gold yarns, receding into the distance"),
  loupe: img("inspection-loupe.jpg", "A magnifying loupe over ecru woven fabric, showing the weave structure enlarged"),
  drafting: img("pattern-drafting.jpg", "Navy twill fabric marked with gold pattern-drafting lines and a grainline"),
  navyTwill: img("navy-twill.jpg", "Dark navy twill fabric in deep folds"),
} satisfies Record<string, ImageEntry>;

export type ImageKey = keyof typeof images;

export function resolveImage(key: string | undefined, fallback: ImageKey = "heroSilk"): ImageEntry {
  if (key && key in images) return images[key as ImageKey];
  if (key && (key.startsWith("/media/") || key.startsWith("/images/"))) {
    return { src: key, alt: "", width: 1600, height: 1200 };
  }
  return images[fallback];
}

export const imageKeys = Object.keys(images) as ImageKey[];
